function renderOrders(){let en=db.language==='en',os=[...db.orders].reverse();$('#orderTab').innerHTML=`<div class="orderList">${os.map(o=>`<details class="orderCard orderDrop"><summary><div><h3>#${String(o.id).padStart(3,'0')} · ${money(o.total)}</h3><p>${new Date(o.date).toLocaleString(en?'en-AU':'th-TH')} · ${o.staff}</p></div><div class="orderSummaryRight">${o.status==='cancelled'?'':iconPayment(o.method)}${o.status==='cancelled'?`<span class="cancelBadge">${en?'Cancelled':'ยกเลิก'}</span>`:''}<span class="chev">⌄</span></div></summary><div class="orderItems">${o.items.map(i=>`<div><span>${i.qty} × ${i.name}${i.variant?' · '+i.variant:''}</span><b>${money(i.qty*i.price)}</b></div>`).join('')}</div>${o.status==='cancelled'?`<div class="cancelNotice"><b>${en?'Cancelled':'ยกเลิก'}</b><span>${o.cancelReason||(en?'This order was cancelled':'ออเดอร์นี้ถูกยกเลิก')}</span></div>`:''}<div class="actions"><button onclick="printReceipt(${o.id})"><svg><use href="#print"/></svg>${en?'Receipt':'ใบเสร็จ'}</button><button class="warm" onclick="printKitchen(${o.id})"><svg><use href="#chef"/></svg>${en?'Print prep ticket':'พิมพ์เตรียมอาหาร'}</button>${o.status!=='cancelled'?`<button class="danger" onclick="cancelPaid(${o.id})">${en?'Cancel order':'ยกเลิกออเดอร์'}</button>`:`<span class="cancelBadge cancelBadgeAction">${en?'Cancelled':'ยกเลิกแล้ว'}</span>`}</div></details>`).join('')||`<div class="emptyState">${en?'No orders yet':'ยังไม่มีออเดอร์'}</div>`}</div>`}
function renderPreorders(){let en=db.language==='en';const metaIcon=(type)=>type==='date'?`<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="5.5" width="17" height="15" rx="3"/><path d="M8 3.5v4M16 3.5v4M3.5 10h17"/></svg>`:type==='time'?`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5v5l3.5 2"/></svg>`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7.1 3.8 9.5 7l-1.8 2.2c1.4 2.8 3.3 4.7 6.1 6.1l2.2-1.8 3.2 2.4c.5.4.6 1.1.3 1.7l-1 1.8c-.4.7-1.1 1.1-1.9 1-7-.8-12.2-6-13-13-.1-.8.3-1.5 1-1.9l1.8-1c.6-.3 1.3-.2 1.7.3Z"/></svg>`;$('#orderTab').innerHTML=`<div class="pageHead"><div><h2>${en?'Pre-orders':'รายการสั่งล่วงหน้า'}</h2><p>${en?'Customer, pickup date, time, phone and items':'ลูกค้า วันที่รับ เวลา เบอร์โทร และรายการที่สั่ง'}</p></div><button id="newPre" class="primary"><svg><use href="#calendar"/></svg>${en?'New pre-order':'สร้างออเดอร์ล่วงหน้า'}</button></div><div class="orderList preorderList">${[...db.preorders].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(p=>`<details class="orderCard orderDrop preorderCard"><summary><div class="preSummaryMain"><div class="preCustomerLine"><h3>${p.customer}</h3><span class="preBadge">${en?'Pre-order':'จองล่วงหน้า'}</span></div><div class="preMeta"><span>${metaIcon('date')}<small>${en?'Pickup date':'วันที่รับ'}</small><b>${p.date}</b></span><span>${metaIcon('time')}<small>${en?'Time':'เวลา'}</small><b>${p.time}</b></span>${p.phone?`<span>${metaIcon('phone')}<small>${en?'Phone':'เบอร์โทร'}</small><b>${p.phone}</b></span>`:''}</div></div><div class="orderSummaryRight"><span class="preItemCount">${p.items.reduce((n,i)=>n+(i.qty||0),0)} ${en?'items':'ชิ้น'}</span><span class="chev">⌄</span></div></summary><div class="preOrderHead"><span>${en?'Item':'เมนู'}</span><span>${en?'Price':'ราคา'}</span><span>${en?'Qty':'จำนวน'}</span></div><div class="orderItems preOrderItems">${p.items.map(i=>`<div><span>${i.name} ${i.variant||''}</span><b>${money(i.price)}</b><strong>${i.qty}</strong></div>`).join('')}</div>${p.note?`<div class="note"><b>${en?'Note':'หมายเหตุ'}</b><span>${p.note}</span></div>`:''}<div class="actions"><button class="warm" onclick="printPreKitchen(${p.id})"><svg><use href="#print"/></svg>${en?'Print prep ticket':'พิมพ์เตรียมอาหาร'}</button><button class="danger" onclick="deletePre(${p.id})">${en?'Delete':'ลบ'}</button></div></details>`).join('')||`<div class="emptyState">${en?'No pre-orders yet':'ยังไม่มีรายการสั่งล่วงหน้า'}</div>`}</div>`;$('#newPre').onclick=openPreorder}
function openPreorder(){preCart=[];$('#preName').value='';$('#prePhone').value='';$('#preDate').value=dateKey(new Date());$('#preTime').value='10:00';$('#preNote').value='';renderPreProducts();$('#preorderModal').classList.remove('hidden')}
function renderPreProducts(){let en=db.language==='en',products=db.products.filter(p=>p.enabled!==false);$('#preProducts').innerHTML=`<div class="prePickerIntro"><div><b>${en?'Choose items':'เลือกเมนู'}</b><span>${en?'Tap a menu to add it. Tap again to increase quantity.':'แตะเมนูเพื่อเลือก แตะซ้ำเพื่อเพิ่มจำนวน'}</span></div><span class="preSelectedTotal">${preCart.reduce((n,i)=>n+i.qty,0)} ${en?'selected':'รายการ'}</span></div><div class="preMenuGrid">`+products.map(p=>{let x=preCart.find(i=>i.id===p.id),qty=x?x.qty:0;return `<button type="button" class="preMenuCard ${qty?'selected':''}" data-id="${p.id}"><span class="preMenuName">${p.name}</span><span class="preMenuPrice">${money(p.price)}</span>${qty?`<span class="preMenuBadge">${qty}</span><span class="preMenuMinus" data-minus="1" aria-label="${en?'Remove one':'ลดจำนวน'}">−</span>`:''}</button>`}).join('')+`</div>`;$$('#preProducts .preMenuCard').forEach(card=>card.onclick=e=>{let p=db.products.find(x=>x.id===card.dataset.id),x=preCart.find(x=>x.id===p.id);if(e.target.closest('[data-minus]')){e.stopPropagation();if(x){x.qty--;if(x.qty<=0)preCart=preCart.filter(i=>i!==x)}}else if(x)x.qty++;else preCart.push({id:p.id,name:p.name,variant:'',price:p.price,qty:1});clickSound(520,.045);renderPreProducts()})}
$('#preorderForm').onsubmit=e=>{e.preventDefault();if(!preCart.length)return alert(db.language==='en'?'Please choose at least one item':'กรุณาเลือกเมนู');db.preorders.push({id:Date.now(),customer:$('#preName').value,phone:$('#prePhone').value,date:$('#preDate').value,time:$('#preTime').value,note:$('#preNote').value,items:structuredClone(preCart)});save();$('#preorderModal').classList.add('hidden');renderPreorders();clickSound(760,.12);db.language==='en'?null:speakThai('มีรายการสั่งล่วงหน้าใหม่')};
window.deletePre=id=>{db.preorders=db.preorders.filter(x=>x.id!==id);save();renderPreorders()};window.printPreKitchen=id=>{let p=db.preorders.find(x=>x.id===id);printDoc(`<div class="ticket kitchenTicket"><h1>PRE-ORDER</h1><h2>${p.customer}</h2><h3>${p.date} · ${p.time}</h3><hr>${p.items.map(i=>`<div class="kitem"><b>${i.qty} × ${i.name}</b></div>`).join('')}<hr><b>หมายเหตุ: ${p.note||'-'}</b></div>`)};
function renderKitchen(){let en=db.language==='en',active=db.orders.filter(o=>o.status==='paid').slice(-20).reverse();$('#orderTab').innerHTML=`<div class="kitchenGrid"><div><h2>${en?'Orders to prepare':'รายการที่ต้องเตรียม'}</h2>${active.map(o=>`<details class="kitchenDrop"><summary><b>Order #${String(o.id).padStart(3,'0')}</b><span>${o.items.reduce((a,i)=>a+i.qty,0)} ${en?'items':'ชิ้น'} ⌄</span></summary><div class="kitchenInner">${o.items.map(i=>`<div><b>${i.qty} × ${i.name}</b><span>${i.variant||''}</span></div>`).join('')}<button class="warm" onclick="printKitchen(${o.id})"><svg><use href="#print"/></svg>${en?'Print prep ticket':'พิมพ์ใบเตรียม'}</button></div></details>`).join('')||`<div class="emptyState">${en?'Nothing to prepare':'ไม่มีรายการ'}</div>`}</div><div><h2>${en?'Ingredients / prep notes':'ข้อมูลวัตถุดิบ / การเตรียม'}</h2>${db.categories.map(c=>`<section class="ingredientGroup"><h3>${c.name}</h3>${db.products.filter(p=>p.cat===c.id).map(p=>`<div><b>${p.name}</b><span>${p.prep||p.desc||(en?'Not specified':'ยังไม่ได้ระบุ')}</span></div>`).join('')}</section>`).join('')}</div></div>`}
function statsFor(k){
  const dayOrders=db.orders.filter(o=>(o.localDate||dateKey(o.date))===k);
  const paid=dayOrders.filter(o=>o.status!=='cancelled'&&(o.status==='paid'||o.method==='cash'||o.method==='qr'));
  const cancelled=dayOrders.filter(o=>o.status==='cancelled').length;
  const sales=paid.reduce((sum,o)=>sum+(+o.total||0),0);
  const cash=paid.filter(o=>o.method==='cash').reduce((sum,o)=>sum+(+o.total||0),0);
  const qr=paid.filter(o=>o.method==='qr').reduce((sum,o)=>sum+(+o.total||0),0);
  const cost=paid.reduce((sum,o)=>sum+(o.items||[]).reduce((sub,i)=>{
    const product=db.products.find(p=>p.id===i.id)||{};
    const variant=String(i.variant||'').toLowerCase();
    const isHalf=variant.includes('ครึ่ง')||variant.includes('half');
    const unitCost=isHalf?(+product.halfCost||(+product.cost||0)/2):(+product.cost||0);
    return sub+unitCost*(+i.qty||0);
  },0),0);
  return {paid,cancelled,sales,cash,qr,cost,profit:sales-cost};
}
function statHtml(s){let en=db.language==='en';return `<div><span>${en?'Total sales':'ยอดขายรวม'}</span><b>${money(s.sales)}</b></div><div><span>${en?'Cash':'เงินสด'}</span><b>${money(s.cash)}</b></div><div><span>QR</span><b>${money(s.qr)}</b></div><div><span>${en?'Completed orders':'ออเดอร์สำเร็จ'}</span><b>${s.paid.length} ${en?'orders':'ออเดอร์'}</b></div><div><span>${en?'Cost':'ต้นทุน'}</span><b>${money(s.cost)}</b></div><div><span>${en?'Estimated profit':'กำไรโดยประมาณ'}</span><b>${money(s.profit)}</b></div><div><span>${en?'Cancelled':'ยกเลิก'}</span><b>${s.cancelled} ${en?'orders':'ออเดอร์'}</b></div>`}
function todayDashboard(s){let en=db.language==='en',sum=Math.max(1,s.cost+Math.max(0,s.profit)),profitPct=Math.max(0,Math.min(100,Math.max(0,s.profit)/sum*100)),costPct=100-profitPct,profitWins=s.profit>=s.cost;return `<div class="reportHero"><div><span class="reportEyebrow">${en?'TODAY AT A GLANCE':'ภาพรวมวันนี้'}</span><h3>${money(s.sales)}</h3><p>${en?'Total sales today':'ยอดขายรวมของวันนี้'}</p></div><div class="reportOrderPill"><svg><use href="#ordersIcon"/></svg><b>${s.paid.length}</b><span>${en?'completed':'สำเร็จ'}</span></div></div><div class="reportMiniGrid"><div class="metricMotion"><svg><use href="#wallet"/></svg><span>${en?'Cash':'เงินสด'}</span><b>${money(s.cash)}</b></div><div class="metricMotion delay1"><svg><use href="#qr"/></svg><span>PromptPay QR</span><b>${money(s.qr)}</b></div><div class="metricMotion delay2"><svg><use href="#cancelDoc"/></svg><span>${en?'Cancelled':'ยกเลิก'}</span><b>${s.cancelled}</b></div></div><div class="profitCard splitProfitCard"><div class="profitHead"><div><span>${en?'PROFIT & COST':'กำไรและต้นทุน'}</span><h3>${en?'Today’s balance':'สมดุลของวันนี้'}</h3></div><span class="profitMood ${profitWins?'good':'warn'}">${profitWins?(en?'Profit leads':'กำไรมากกว่า'):(en?'Cost leads':'ต้นทุนมากกว่า')}</span></div><div class="splitLabels"><div class="${profitWins?'loser':'winner'}"><b>${en?'Cost':'ต้นทุน'}</b><strong>${money(s.cost)}</strong><em>${costPct.toFixed(1)}%</em></div><div class="${profitWins?'winner':'loser'} right"><b>${en?'Profit':'กำไร'}</b><strong>${money(s.profit)}</strong><em>${profitPct.toFixed(1)}%</em></div></div><div class="splitTrack"><i class="costSide ${profitWins?'low':'high'}" style="width:${costPct}%"></i><i class="profitSide ${profitWins?'high':'low'}" style="width:${profitPct}%"></i><span class="splitCenter"></span></div></div>`}
function renderReports(){let today=dateKey(new Date()),s=statsFor(today);$('#todayStats').className='todayDashboard';$('#todayStats').innerHTML=todayDashboard(s);if(!$('#reportDate').value)$('#reportDate').value=today;renderPast()}
function renderPast(){let key=$('#reportDate').value,s=statsFor(key);$('#pastStats').className='stats';$('#pastStats').innerHTML=statHtml(s);let rows={};s.paid.forEach(o=>o.items.forEach(i=>{let k=i.id+'|'+i.variant;if(!rows[k])rows[k]={name:i.name+(i.variant?' · '+i.variant:''),qty:0,total:0,cash:0,qr:0};rows[k].qty+=i.qty;rows[k].total+=i.qty*i.price;rows[k][o.method]+=i.qty*i.price}));let en=db.language==='en';$('#productSales').innerHTML=`<div class="tr th"><span>${en?'Product':'สินค้า'}</span><span>${en?'Qty':'จำนวน'}</span><span>${en?'Payment':'ชำระ'}</span><span>${en?'Sales':'ยอด'}</span></div>`+Object.values(rows).map(r=>`<div class="tr"><span>${r.name}</span><span>${r.qty}</span><span>${r.cash?iconPayment('cash'):''}${r.qr?iconPayment('qr'):''}</span><b>${money(r.total)}</b></div>`).join('')}
$('#reportDate').onchange=renderPast;$('#printSummary').onclick=()=>{let k=dateKey(new Date()),s=statsFor(k);printDoc(`<div class="ticket"><img src="logo.png"><h2>สรุปปิดยอด ${k}</h2><hr><div class="r"><span>ยอดขาย</span><b>${money(s.sales)}</b></div><div class="r"><span>เงินสด</span><b>${money(s.cash)}</b></div><div class="r"><span>QR</span><b>${money(s.qr)}</b></div><div class="r"><span>ต้นทุน</span><b>${money(s.cost)}</b></div><div class="r"><span>กำไรโดยประมาณ</span><b>${money(s.profit)}</b></div><div class="r"><span>ออเดอร์</span><b>${s.paid.length}</b></div><div class="r"><span>ยกเลิก</span><b>${s.cancelled}</b></div></div>`)};
let selectedStock=new Set();
function renderStock(){
  $('#stockList').innerHTML=db.categories.map(c=>`<section class="stockGroup"><h3>${c.name}</h3>${db.products.filter(p=>p.cat===c.id).map(p=>`<div class="stockRow ${selectedStock.has(p.id)?'selected':''}" data-stock-id="${p.id}"><div class="stockPick" onclick="toggleStockPick('${p.id}')"><b>${p.name}</b><span>${p.stock<=3?'สต๊อกต่ำ':''}</span><small>${selectedStock.has(p.id)?'เลือกแล้ว — ใช้ปุ่มด้านบนปรับพร้อมกัน':'แตะชื่อเพื่อเลือก'}</small></div><button onclick="stockChange('${p.id}',-1)">−</button><strong>${p.stock}</strong><button onclick="stockChange('${p.id}',1)">+</button></div>`).join('')||'<small>ไม่มีสินค้า</small>'}</section>`).join('');
  $('#selectAllStock').textContent=selectedStock.size===db.products.length&&db.products.length?'ยกเลิกการเลือกทั้งหมด':'เลือกทั้งหมด';
}
window.toggleStockPick=id=>{selectedStock.has(id)?selectedStock.delete(id):selectedStock.add(id);renderStock()};
window.stockChange=(id,d)=>{let p=db.products.find(x=>x.id===id);p.stock=Math.max(0,+p.stock+d);save();renderStock();renderProducts()};
$('#selectAllStock').onclick=()=>{if(selectedStock.size===db.products.length)selectedStock.clear();else db.products.forEach(p=>selectedStock.add(p.id));renderStock()};
function bulk(d){selectedStock.forEach(id=>{let p=db.products.find(p=>p.id===id);if(p)p.stock=Math.max(0,+p.stock+d)});save();renderStock();renderProducts()}
$('#bulkPlus').onclick=()=>bulk(1);$('#bulkMinus').onclick=()=>bulk(-1);
