$('#addCategory').onclick=()=>{const m=$('#categoryModal'),i=$('#newCategoryName');m.classList.remove('hidden');i.value='';setTimeout(()=>i.focus(),80)};$('#cancelCategory').onclick=()=>$('#categoryModal').classList.add('hidden');$('#confirmCategory').onclick=()=>{let name=$('#newCategoryName').value.trim();if(!name)return $('#newCategoryName').focus();if(db.categories.some(c=>c.name.toLowerCase()===name.toLowerCase()))return alert('มีหมวดหมู่นี้อยู่แล้ว');db.categories.push({id:'cat'+Date.now(),name});save();$('#categoryModal').classList.add('hidden');renderManage();renderCats();clickSound(720,.08)};$('#newCategoryName').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#confirmCategory').click()}});$('#addProduct').onclick=()=>openEditor();
