function openEditor(p){fillCatSelect();$('#imagePreview').dataset.cropped='';$('#halfImagePreview').dataset.cropped='';$('#editImage').value='';$('#editHalfImage').value='';$('#editorTitle').textContent=p?'แก้ไขเมนู':'เพิ่มเมนู';$('#editId').value=p?.id||'';$('#editName').value=p?.name||'';$('#editCategory').value=p?.cat||db.categories[0]?.id||'';$('#editPrice').value=p?.price||'';$('#editHalf').value=p?.half||'';$('#editHalfCost').value=p?.halfCost||'';$('#editHalfName').value=p?.halfName||'ครึ่งโลฟ';$('#editCost').value=p?.cost||'';$('#halfImagePreview').innerHTML=p?.halfImg?`<img src="${p.halfImg}">`:'';$('#editStock').value=p?.stock??0;$('#editPrep').value=p?.prep||'';$('#imagePreview').innerHTML=p?.img?`<img src="${p.img}">`:'';$('#editorModal').classList.remove('hidden');if($('#hasHalf')){$('#hasHalf').checked=!!p?.half;$('#halfFields').classList.toggle('hidden',!$('#hasHalf').checked)}}
