$('#productForm').onsubmit=e=>{e.preventDefault();let id=$('#editId').value||'p'+Date.now(),oldp=db.products.find(p=>p.id===id),file=$('#editImage').files[0],halfFile=$('#editHalfImage').files[0],cropped=$('#imagePreview').dataset.cropped||null,halfCropped=$('#halfImagePreview').dataset.cropped||null;let build=(img,halfImg)=>{let p={id,name:$('#editName').value,cat:$('#editCategory').value,price:+$('#editPrice').value,half:$('#editHalf').value?+$('#editHalf').value:null,halfCost:+$('#editHalfCost').value||0,halfName:$('#editHalfName').value||'ครึ่งโลฟ',cost:+$('#editCost').value||0,stock:+$('#editStock').value||0,prep:$('#editPrep').value,img:img||oldp?.img||'logo.png',halfImg:halfImg||oldp?.halfImg||img||oldp?.img||'logo.png',desc:oldp?.desc||''};if(oldp)Object.assign(oldp,p);else db.products.push(p);save();$('#editorModal').classList.add('hidden');renderManage();renderProducts()};let read=f=>new Promise(r=>{if(!f)return r(null);let x=new FileReader();x.onload=()=>r(x.result);x.readAsDataURL(f)});Promise.all([read(file),read(halfFile)]).then(([a,b])=>build(cropped||a,halfCropped||b))};
